    if (email != null) "email": email!,
    if (currencyCode != null) "currency_code": currencyCode!,
    if (shippingAddressId != null) "shipping_address_id": shippingAddressId!,
    if (billingAddressId != null) "billing_address_id": billingAddressId!,
