}

/// The workflow execution's context.
class WorkflowExecutionContext {
  WorkflowExecutionContext({
    this.data,
    this.compensate,
    this.errors,
  });

  /// The context's data.
  final Map<String, dynamic>? data;
  /// The context's compensate.
  final Map<String, dynamic>? compensate;
  /// The context's errors.
  final List<Map<String, dynamic>>? errors;

  factory WorkflowExecutionContext.fromJson(Map<String, dynamic> json) => WorkflowExecutionContext(
    data: json["data"] as Map<String, dynamic>?,
    compensate: json["compensate"] as Map<String, dynamic>?,
    errors: (json["errors"] as List?)?.map((e) => e as Map<String, dynamic>?).toList().cast<Map<String, dynamic>>(),
  );

  Map<String, dynamic> toJson() => {
    if (data != null) "data": data!,
    if (compensate != null) "compensate": compensate!,
    if (errors != null) "errors": errors!.map((e) => e).toList(),
  };
}

/// The step's definition details.
class WorkflowExecutionDefinition {
  WorkflowExecutionDefinition({
    this.async,
    this.compensateAsync,
    this.noCompensation,
    this.continueOnPermanentFailure,
    this.skipOnPermanentFailure,
    this.maxRetries,
    this.noWait,
    this.retryInterval,
    this.retryIntervalAwaiting,
    this.saveResponse,
    this.timeout,
    this.autoRetry,
    this.maxAwaitingRetries,
  });

  /// Whether the step is async.
  final bool? async;
  /// Whether the compensation function of the step is async.
  final bool? compensateAsync;
  /// Whether the step doesn't have a compensation function.
  final bool? noCompensation;
  /// Whether the workflow should continue executing even if its status is changed to failed.
  final bool? continueOnPermanentFailure;
  final dynamic skipOnPermanentFailure;
  /// The maximum number of times to retry the step.
  final num? maxRetries;
  /// Whether the workflow shouldn't wait for the step to finish before moving to the next step.
  final bool? noWait;
  /// The interval in seconds between retry attempts when the step fails.
  final num? retryInterval;
  /// The interval in seconds to retry a step even if its status is `waiting_response`.
  final num? retryIntervalAwaiting;
  /// Whether the step's response is stored.
  final bool? saveResponse;
  /// The maximum time in seconds to wait for this step to complete. If the step exceeds this time, the step's state is changed to `timeout`, but the step continues e
  final num? timeout;
  /// Whether the step should be automatically retried if it fails.
  final bool? autoRetry;
  /// The maximum number of times to retry the step while it's in the `waiting_response` state.
  final num? maxAwaitingRetries;

  factory WorkflowExecutionDefinition.fromJson(Map<String, dynamic> json) => WorkflowExecutionDefinition(
    async: json["async"] as bool?,
    compensateAsync: json["compensateAsync"] as bool?,
    noCompensation: json["noCompensation"] as bool?,
    continueOnPermanentFailure: json["continueOnPermanentFailure"] as bool?,
    skipOnPermanentFailure: json["skipOnPermanentFailure"],
    maxRetries: json["maxRetries"] as num?,
    noWait: json["noWait"] as bool?,
    retryInterval: json["retryInterval"] as num?,
    retryIntervalAwaiting: json["retryIntervalAwaiting"] as num?,
    saveResponse: json["saveResponse"] as bool?,
    timeout: json["timeout"] as num?,
    autoRetry: json["autoRetry"] as bool?,
    maxAwaitingRetries: json["maxAwaitingRetries"] as num?,
  );

  Map<String, dynamic> toJson() => {
    if (async != null) "async": async!,
    if (compensateAsync != null) "compensateAsync": compensateAsync!,
    if (noCompensation != null) "noCompensation": noCompensation!,
    if (continueOnPermanentFailure != null) "continueOnPermanentFailure": continueOnPermanentFailure!,
    if (skipOnPermanentFailure != null) "skipOnPermanentFailure": skipOnPermanentFailure!,
    if (maxRetries != null) "maxRetries": maxRetries!,
    if (noWait != null) "noWait": noWait!,
    if (retryInterval != null) "retryInterval": retryInterval!,
    if (retryIntervalAwaiting != null) "retryIntervalAwaiting": retryIntervalAwaiting!,
    if (saveResponse != null) "saveResponse": saveResponse!,
    if (timeout != null) "timeout": timeout!,
    if (autoRetry != null) "autoRetry": autoRetry!,
    if (maxAwaitingRetries != null) "maxAwaitingRetries": maxAwaitingRetries!,
  };
}

